@using sv_63b897a8500c40f1ab541ae3b182c892.Services

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link w-100 text-start @(ActiveSection == section.Key ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                    <span class="me-2">@section.Icon</span>
                    @section.Label
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private record SectionItem(string Key, string Label, string Icon);

    private static readonly SectionItem[] Sections = new[]
    {
        new SectionItem("Profile", "Profile", "👤"),
        new SectionItem("Notifications", "Notifications", "🔔"),
        new SectionItem("Security", "Security", "🔒"),
        new SectionItem("Appearance", "Appearance", "🎨"),
    };
}

@using sv_63b897a8500c40f1ab541ae3b182c892.Services
@inject ISettingsService SettingsService

<div class="profile-section">
    <h4>Profile Settings</h4>

    @if (_profile is null)
    {
        <p>Loading...</p>
        return;
    }

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_displayName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="_bio"></textarea>
            </div>
        </div>
        <div class="col-md-4 text-center">
            <div class="avatar-preview mb-2">
                <img src="@_avatarUrl" alt="Avatar" class="rounded-circle" style="width: 120px; height: 120px; object-fit: cover;" />
            </div>
            <small class="text-muted d-block text-truncate" style="max-width: 200px;" title="@_avatarUrl">@_avatarUrl</small>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
    </div>
</div>

@code {
    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";
    private string? _message;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        LoadFromProfile(_profile);
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _message = "Profile saved successfully!";
    }

    private void DiscardChanges()
    {
        if (_profile is not null)
        {
            LoadFromProfile(_profile);
        }
        _message = null;
    }
}

@using sv_63b897a8500c40f1ab541ae3b182c892.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    <h4>Notification Preferences</h4>

    @if (_prefs is null)
    {
        <p>Loading...</p>
